sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == oldValue) return;

    g_form.getReference('caller_id', vipCallerCallback);
}

function vipCallerCallback(caller) {
    var callerLabel = g_form.getLabel('caller_id');
    var callerField = g_form.getDisplayBox('caller_id');

    if (!callerLabel || !callerField) return;

    // Check for VIP status
    if (caller.vip == 'true' || caller.vip == true || caller.vip == '1') {
        var bgPosition = "95% 55%";
        if (document.documentElement.getAttribute('data-doctype') == 'true') {
            bgPosition = "5% 45%";
        }

        callerLabel.style.backgroundImage = "url(images/icons/user.gif)";
        callerLabel.style.backgroundRepeat = "no-repeat";
        callerLabel.style.backgroundPosition = bgPosition;
        callerLabel.style.paddingLeft = "30px";

        callerField.style.color = "red";
    } else {
        callerLabel.style.backgroundImage = "";
        callerLabel.style.paddingLeft = "";
        callerField.style.color = "";
    }
}
